body.script:
// 
const basePath = window.location.pathname.substring(0, window.location.pathname.lastIndexOf('/') + 1);

const encodeUrl = (url) => {
  if (!url) return url;
  return encodeURIComponent(
    url.toString().split('').map((char, ind) => 
      ind % 2 ? String.fromCharCode(char.charCodeAt() ^ 2) : char
    ).join('')
  );
};

self.__uv$config = {
  prefix: basePath + 'service/',
  bare: 'https://bare.benroberts.net/',
  encodeUrl: (typeof Ultraviolet !== 'undefined' && Ultraviolet.codec && Ultraviolet.codec.xor) ? Ultraviolet.codec.xor.encode : encodeUrl,
  handler: basePath + 'uv/uv.handler.js',
  client: basePath + 'uv/uv.client.js',
  bundle: basePath + 'uv/uv.bundle.js',
  config: basePath + 'uv/uv.config.js',
  sw: basePath + 'uv/uv.sw.js',
};

let swRegistered = false;
const status = document.getElementById("status");
const input = document.getElementById("url-input");
const container = document.getElementById("viewport-container");
const frame = document.getElementById("app-frame");

async function registerSW() {
  if (!("serviceWorker" in navigator)) {
    status.textContent = "Service workers are not supported in this browser context.";
    return;
  }

  try {
    await navigator.serviceWorker.register(basePath + "sw.js", {
      scope: __uv$config.prefix
    });
    await navigator.serviceWorker.ready;
    swRegistered = true;
    status.textContent = "Proxy service is ready.";
    console.log("Service Worker registered with scope: " + __uv$config.prefix);
  } catch (err) {
    swRegistered = false;
    status.textContent = "Setup failed: " + err.message;
    console.error("SW error:", err);
  }
}

async function launch() {
  const query = input.value.trim();
  if (!query) return;

  status.textContent = "Opening...";

  if (!swRegistered) {
    await registerSW();
  }

  let url;
  if (/^https?:\/\//i.test(query)) {
    url = query;
  } else if (/^[^\s.]+\.[^\s]+$/.test(query) && !query.includes(" ")) {
    url = "https://" + query;
  } else {
    url = "https://duckduckgo.com/?q=" + encodeURIComponent(query);
  }

  frame.src = __uv$config.prefix + __uv$config.encodeUrl(url);
  container.style.display = "flex";
  status.textContent = "Loaded: " + url;
}

function closeFrame() {
  frame.src = "about:blank";
  container.style.display = "none";
}

function panic() {
  window.location.replace("https://classroom.google.com");
}

input.addEventListener("keydown", (e) => {
  if (e.key === "Enter") launch();
});

window.addEventListener("load", () => {
  registerSW();
});
//
